  ]
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "revenue_growth",
    "granularity": "month",
    "range": "last_6_months"
  }
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "get_dataset",
  "arguments": {
    "name": "market_data",
    "filters": {
      "period": "curr_month"
    }
  }
}
```

